import{_ as l}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as e}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Skills 机制详解：Skills、Prompts、Projects、Subagents 与 MCP 的对比","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/skills/skills-mechanics-explained.md","filePath":"zh/tech/skills/skills-mechanics-explained.md","lastUpdated":1786775996000}'),r={name:"zh/tech/skills/skills-mechanics-explained.md"};function i(o,t,d,n,h,u){return s(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="skills-机制详解-skills、prompts、projects、subagents-与-mcp-的对比" tabindex="-1">Skills 机制详解：Skills、Prompts、Projects、Subagents 与 MCP 的对比 <a class="header-anchor" href="#skills-机制详解-skills、prompts、projects、subagents-与-mcp-的对比" aria-label="Permalink to &quot;Skills 机制详解：Skills、Prompts、Projects、Subagents 与 MCP 的对比&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://claude.com/blog/skills-explained" target="_blank" rel="noreferrer">https://claude.com/blog/skills-explained</a></p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>自引入 Skills 以来，大家对 Claude Agent 生态系统中的各个组件如何协同工作很感兴趣。无论是在 Claude Code 中构建复杂工作流、使用 API 创建企业解决方案，还是在 Claude.ai 上提高生产力，了解何时使用什么工具，可以改变你与 Claude 协作的方式。</p><p>本文将详细解析每个构建块，说明何时使用、如何组合它们以构建强大的 Agent 工作流。</p><hr><h2 id="skills-详解" tabindex="-1">Skills 详解 <a class="header-anchor" href="#skills-详解" aria-label="Permalink to &quot;Skills 详解&quot;">​</a></h2><h3 id="什么是-skills" tabindex="-1">什么是 Skills <a class="header-anchor" href="#什么是-skills" aria-label="Permalink to &quot;什么是 Skills&quot;">​</a></h3><p>Skills 是包含指令、脚本和资源的文件夹，Claude 能够<strong>动态发现并在相关任务中加载</strong>。可以理解为给 Claude 的专业化培训手册。</p><h3 id="工作原理-渐进式加载" tabindex="-1">工作原理：渐进式加载 <a class="header-anchor" href="#工作原理-渐进式加载" aria-label="Permalink to &quot;工作原理：渐进式加载&quot;">​</a></h3><p>Skills 使用渐进式加载优化上下文使用：</p><ol><li><strong>元数据加载</strong>（~100 tokens）：名称和描述首先加载，提供足够信息让 Claude 知道何时激活</li><li><strong>完整指令加载</strong>（&lt;5k tokens）：Skill 匹配时加载</li><li><strong>文件按需加载</strong>：脚本或资源仅在需要时加载</li></ol><h3 id="何时使用-skills" tabindex="-1">何时使用 Skills <a class="header-anchor" href="#何时使用-skills" aria-label="Permalink to &quot;何时使用 Skills&quot;">​</a></h3><ul><li>组织工作流：品牌规范、合规流程、文档模板</li><li>领域专业知识：Excel 公式、PDF 操作、数据分析</li><li>个人偏好：编码模式、研究方法</li><li>需要跨对话持久一致的任务执行</li></ul><p><strong>示例</strong>：创建 brand-guidelines Skill 包含公司的颜色、字体规范和布局规范。当 Claude 创建文档时，自动应用这些标准。</p><hr><h2 id="prompts-详解" tabindex="-1">Prompts 详解 <a class="header-anchor" href="#prompts-详解" aria-label="Permalink to &quot;Prompts 详解&quot;">​</a></h2><h3 id="什么是-prompts" tabindex="-1">什么是 Prompts <a class="header-anchor" href="#什么是-prompts" aria-label="Permalink to &quot;什么是 Prompts&quot;">​</a></h3><p>Prompts 是对话中用自然语言向 Claude 提供的指令，是<strong>临时的、对话式的、反应式的</strong>——你在当下提供上下文和方向。</p><h3 id="何时使用-prompts" tabindex="-1">何时使用 Prompts <a class="header-anchor" href="#何时使用-prompts" aria-label="Permalink to &quot;何时使用 Prompts&quot;">​</a></h3><ul><li><strong>一次性请求</strong>：&quot;总结这篇文章&quot;</li><li><strong>对话式优化</strong>：&quot;让语气更专业&quot;</li><li><strong>即时上下文</strong>：&quot;分析这些数据并识别趋势&quot;</li><li><strong>临时指令</strong>：&quot;格式化为项目符号列表&quot;</li></ul><h3 id="何时从-prompts-升级到-skills" tabindex="-1">何时从 Prompts 升级到 Skills <a class="header-anchor" href="#何时从-prompts-升级到-skills" aria-label="Permalink to &quot;何时从 Prompts 升级到 Skills&quot;">​</a></h3><p>如果在多个对话中反复输入相同的提示词，就是时候创建 Skill 了。</p><p><strong>经验法则</strong>：重复超过 5 次 → 考虑 Skill</p><hr><h2 id="projects-详解" tabindex="-1">Projects 详解 <a class="header-anchor" href="#projects-详解" aria-label="Permalink to &quot;Projects 详解&quot;">​</a></h2><h3 id="什么是-projects" tabindex="-1">什么是 Projects <a class="header-anchor" href="#什么是-projects" aria-label="Permalink to &quot;什么是 Projects&quot;">​</a></h3><p>Projects 是自包含的工作空间，有自己的聊天历史和知识库。每个项目包含 200K 上下文窗口，可以上传文档、提供上下文和设置自定义指令，这些指令在该项目内的所有对话中适用。</p><h3 id="projects-vs-skills" tabindex="-1">Projects vs Skills <a class="header-anchor" href="#projects-vs-skills" aria-label="Permalink to &quot;Projects vs Skills&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Projects</th><th>Skills</th></tr></thead><tbody><tr><td>提供内容</td><td>背景知识</td><td>程序性知识</td></tr><tr><td>加载方式</td><td>项目中始终加载</td><td>仅相关时动态加载</td></tr><tr><td>内容形式</td><td>文档 + 上下文</td><td>指令 + 代码 + 资源</td></tr><tr><td>生命周期</td><td>在项目内持久</td><td>跨对话持久</td></tr></tbody></table><p><strong>核心区别</strong>：</p><ul><li>Projects 说&quot;这是你需要知道的&quot;</li><li>Skills 说&quot;这是如何做事情&quot;</li></ul><p><strong>何时使用 Projects</strong>：</p><ul><li>需要在每次对话中了解的背景知识</li><li>不同项目需要隔离的上下文</li><li>团队协作时共享知识和对话历史</li><li>设置项目特定的语气、视角或方法</li></ul><p><strong>何时组合使用</strong>：需要持久上下文和专业能力时。例如&quot;产品开发&quot;项目包含产品规格和用户研究，结合用于创建技术文档和分析用户反馈的 Skills。</p><hr><h2 id="subagents-详解" tabindex="-1">Subagents 详解 <a class="header-anchor" href="#subagents-详解" aria-label="Permalink to &quot;Subagents 详解&quot;">​</a></h2><h3 id="什么是-subagents" tabindex="-1">什么是 Subagents <a class="header-anchor" href="#什么是-subagents" aria-label="Permalink to &quot;什么是 Subagents&quot;">​</a></h3><p>Subagents 是专业化 AI 助手，有自己的上下文窗口、自定义系统提示和特定工具权限。在 Claude Code 和 Claude Agent SDK 中可用，独立处理离散任务并将结果返回主 agent。</p><h3 id="subagents-vs-skills" tabindex="-1">Subagents vs Skills <a class="header-anchor" href="#subagents-vs-skills" aria-label="Permalink to &quot;Subagents vs Skills&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Subagents</th><th>Skills</th></tr></thead><tbody><tr><td>本质</td><td>完整独立 agent</td><td>可移植的专业能力</td></tr><tr><td>上下文</td><td>有自己的完整上下文</td><td>任何 agent 可加载使用</td></tr><tr><td>工具权限</td><td>可单独配置</td><td>通过加载它的 agent 获得</td></tr><tr><td>典型用途</td><td>独立任务执行</td><td>跨 agent 共享专业知识</td></tr></tbody></table><p><strong>何时使用 Subagents</strong>：</p><ul><li>任务专业化：代码审查、测试生成、安全审计</li><li>上下文管理：保持主对话专注，将专业工作委托</li><li>并行处理：多个 subagents 同时处理不同方面</li><li>工具限制：限制特定 subagents 仅执行安全操作（如只读访问）</li></ul><p><strong>何时使用 Skills</strong>：</p><ul><li>多个 agents 或对话需要相同专业知识</li><li>需要跨 agent 可移植的专业能力</li></ul><p><strong>组合使用</strong>：让 subagents 加载 Skills，获得两者的优势。例如 python-developer subagent 可以使用 pandas-analysis Skill 执行遵循团队约定的数据转换。</p><hr><h2 id="mcp-详解" tabindex="-1">MCP 详解 <a class="header-anchor" href="#mcp-详解" aria-label="Permalink to &quot;MCP 详解&quot;">​</a></h2><h3 id="什么是-mcp" tabindex="-1">什么是 MCP <a class="header-anchor" href="#什么是-mcp" aria-label="Permalink to &quot;什么是 MCP&quot;">​</a></h3><p>MCP（Model Context Protocol）创建了 AI 应用与外部工具和数据源之间的<strong>通用连接层</strong>。</p><h3 id="mcp-vs-skills" tabindex="-1">MCP vs Skills <a class="header-anchor" href="#mcp-vs-skills" aria-label="Permalink to &quot;MCP vs Skills&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>MCP</th><th>Skills</th></tr></thead><tbody><tr><td>本质</td><td>连接协议</td><td>程序性知识</td></tr><tr><td>功能</td><td>连接数据</td><td>教 Claude 做什么</td></tr><tr><td>典型用途</td><td>访问数据库、文件、API</td><td>流程规范、数据处理方法</td></tr><tr><td>持久性</td><td>持续连接</td><td>动态加载</td></tr></tbody></table><p><strong>何时使用 MCP</strong>：</p><ul><li>访问外部数据：Google Drive、Slack、GitHub、数据库</li><li>连接业务工具：CRM、项目管理平台</li><li>连接开发环境：本地文件、IDE、版本控制</li><li>集成自定义系统</li></ul><p><strong>何时使用 Skills</strong>：</p><ul><li>解释如何使用工具：&quot;查询数据库时，先按日期范围过滤&quot;</li><li>说明流程规范：&quot;用这些特定公式格式化 Excel 报告&quot;</li></ul><p><strong>组合使用</strong>：MCP 处理连接，Skills 处理流程知识。</p><hr><h2 id="综合对比" tabindex="-1">综合对比 <a class="header-anchor" href="#综合对比" aria-label="Permalink to &quot;综合对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>Skills</th><th>Prompts</th><th>Projects</th><th>Subagents</th><th>MCP</th></tr></thead><tbody><tr><td>提供内容</td><td>程序性知识</td><td>即时指令</td><td>背景知识</td><td>任务委托</td><td>工具连接</td></tr><tr><td>持久性</td><td>跨对话</td><td>单次对话</td><td>项目内</td><td>跨会话</td><td>持续连接</td></tr><tr><td>包含内容</td><td>指令+代码+资源</td><td>自然语言</td><td>文档+上下文</td><td>完整 agent 逻辑</td><td>工具定义</td></tr><tr><td>加载时机</td><td>按需动态</td><td>每轮</td><td>项目中始终</td><td>调用时</td><td>始终可用</td></tr><tr><td>可含代码</td><td>是</td><td>否</td><td>否</td><td>是</td><td>是</td></tr><tr><td>最佳用途</td><td>专业化能力</td><td>快速请求</td><td>集中上下文</td><td>专业化任务</td><td>数据访问</td></tr></tbody></table><hr><h2 id="组合使用示例-研究-agent-工作流" tabindex="-1">组合使用示例：研究 Agent 工作流 <a class="header-anchor" href="#组合使用示例-研究-agent-工作流" aria-label="Permalink to &quot;组合使用示例：研究 Agent 工作流&quot;">​</a></h2><h3 id="场景-竞争情报分析-agent" tabindex="-1">场景：竞争情报分析 Agent <a class="header-anchor" href="#场景-竞争情报分析-agent" aria-label="Permalink to &quot;场景：竞争情报分析 Agent&quot;">​</a></h3><p><strong>步骤 1：设置 Project</strong> 创建&quot;竞争情报&quot;项目，上传：</p><ul><li>行业报告和市场分析</li><li>竞品产品规格文档</li><li>CRM 中的客户反馈</li><li>之前的研究摘要</li></ul><p>添加项目指令：</p><blockquote><p>&quot;通过我们产品战略的视角分析竞品。关注差异化和新兴市场趋势。用具体证据和可操作建议呈现发现。&quot;</p></blockquote><p><strong>步骤 2：通过 MCP 连接数据源</strong> 启用 MCP 服务器：</p><ul><li>Google Drive（访问共享研究文档）</li><li>GitHub（审查竞品开源仓库）</li><li>Web 搜索（实时市场信息）</li></ul><p><strong>步骤 3：创建专业 Skills</strong> 创建 competitive-analysis Skill：</p><ul><li>公司 Google Drive 导航策略</li><li>竞品分析框架</li><li>数据可视化和呈现标准</li></ul><p><strong>步骤 4：配置 Subagents</strong></p><ul><li><strong>market-researcher</strong>：使用 Read、Grep、Web-search 工具，研究市场趋势和竞品数据</li><li><strong>technical-analyst</strong>：使用 Read、Bash、Grep 工具，分析技术架构和工程决策</li></ul><p><strong>步骤 5：激活工作流</strong></p><p>当你说：&quot;分析我们三大竞品如何定位其新 AI 功能，识别我们可以利用的差距&quot;</p><p>工作流自动：</p><ul><li>Project 上下文加载</li><li>MCP 连接激活，Claude 搜索 Google Drive 最新竞品简报并拉取 GitHub 数据</li><li>competitive-analysis Skill 提供分析框架</li><li>Subagents 并行执行</li><li>你通过 Prompts 提供进一步指导：&quot;尤其关注医疗健康企业客户&quot;</li></ul><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="skills-vs-subagents-何时用哪个" tabindex="-1">Skills vs Subagents：何时用哪个？ <a class="header-anchor" href="#skills-vs-subagents-何时用哪个" aria-label="Permalink to &quot;Skills vs Subagents：何时用哪个？&quot;">​</a></h3><ul><li><strong>Skills</strong>：想让任何 Claude 实例都能加载和使用的通用能力</li><li><strong>Subagents</strong>：需要完整、自包含的 agent 处理独立工作流时</li><li><strong>组合</strong>：需要既有 subagent 独立性又有专业知识的场景</li></ul><h3 id="skills-vs-prompts-何时用哪个" tabindex="-1">Skills vs Prompts：何时用哪个？ <a class="header-anchor" href="#skills-vs-prompts-何时用哪个" aria-label="Permalink to &quot;Skills vs Prompts：何时用哪个？&quot;">​</a></h3><ul><li><strong>Prompts</strong>：一次性指令、即时上下文、对话式往返</li><li><strong>Skills</strong>：需要反复使用的程序或专业知识</li><li><strong>组合</strong>：Prompts 提供基础专业知识，Prompts 提供具体上下文和细化</li></ul><h3 id="skills-vs-projects-何时用哪个" tabindex="-1">Skills vs Projects：何时用哪个？ <a class="header-anchor" href="#skills-vs-projects-何时用哪个" aria-label="Permalink to &quot;Skills vs Projects：何时用哪个？&quot;">​</a></h3><ul><li><strong>Projects</strong>：需要影响所有对话的背景知识和上下文</li><li><strong>Skills</strong>：需要程序性知识和按需激活的可执行代码</li><li><strong>组合</strong>：既有持久上下文又有专业能力</li></ul><h3 id="subagents-能使用-skills-吗" tabindex="-1">Subagents 能使用 Skills 吗？ <a class="header-anchor" href="#subagents-能使用-skills-吗" aria-label="Permalink to &quot;Subagents 能使用 Skills 吗？&quot;">​</a></h3><p>能。在 Claude Code 和 Agent SDK 中，subagents 可以像主 agent 一样访问和使用 Skills。</p><h3 id="如何开始" tabindex="-1">如何开始？ <a class="header-anchor" href="#如何开始" aria-label="Permalink to &quot;如何开始？&quot;">​</a></h3><p><strong>Claude.ai 用户</strong>：</p><ol><li>Settings → Features 启用 Skills</li><li>claude.ai/projects 创建第一个项目</li><li>尝试将项目知识与 Skills 结合</li></ol><p><strong>API 开发者</strong>：</p><ul><li>探索 <a href="https://docs.anthropic.com" target="_blank" rel="noreferrer">Skills API 文档</a></li><li>查看 <a href="https://platform.claude.com/cookbook/skills-notebooks-01-skills-introduction" target="_blank" rel="noreferrer">Skills Cookbook</a></li></ul><p><strong>Claude Code 用户</strong>：</p><ul><li>通过<a href="https://code.claude.com/docs/en/plugin-marketplaces" target="_blank" rel="noreferrer">插件市场</a>安装 Skills</li><li>查看 <a href="https://platform.claude.com/cookbook/skills-notebooks-01-skills-introduction" target="_blank" rel="noreferrer">Skills Cookbook</a></li></ul>',94)])])}const m=l(r,[["render",i]]);export{b as __pageData,m as default};
